use cowork_contracts::RunSpec;
use serde_json::{Value, json};
pub fn model_tool_catalog(spec: &RunSpec) -> Value {
    if spec.agent_config.as_ref().and_then(|c| c.execution_mode)
        == Some(cowork_contracts::AgentExecutionMode::Plan)
    {
        return json!([]);
    }
    let catalog = json!([
      {"type":"function","function":{"name":"delegate_agents","description":"Delegate bounded subtasks to roles explicitly permitted by this workflow. Delegated agents inherit only the intersection of the parent, selected role and requested rights. Use only roles and capabilities listed in the system context. Submit this as the last tool call in the turn. The manager waits until its children finish and then receives their results.","parameters":{"type":"object","properties":{"requests":{"type":"array","minItems":1,"maxItems":32,"items":{"type":"object","properties":{"role_id":{"type":"string"},"goal":{"type":"string"},"rights":{"type":"object","properties":{"tools":{"type":"array","items":{"type":"string"}},"folders":{"type":"array","items":{"type":"string"}}},"required":["tools","folders"],"additionalProperties":false},"budgets":{"type":"object","properties":{"max_steps":{"type":"integer"},"max_seconds":{"type":"integer"},"max_output_tokens":{"type":"integer"},"max_total_tokens":{"type":"integer"}},"required":["max_steps","max_seconds","max_output_tokens","max_total_tokens"],"additionalProperties":false}},"required":["role_id","goal","rights","budgets"],"additionalProperties":false}}},"required":["requests"],"additionalProperties":false}}},
      {"type":"function","function":{"name":"create_artifact","description":"Create a versioned text result inside this order. Requires the user's configured permission.",
        "parameters":{"type":"object","properties":{"name":{"type":"string"},"content":{"type":"string"}},"required":["name","content"],"additionalProperties":false}}},
      {"type":"function","function":{"name":"list_artifacts","description":"List this order's existing result metadata.",
        "parameters":{"type":"object","properties":{},"additionalProperties":false}}},
      {"type":"function","function":{"name":"read_artifact","description":"Read an artifact belonging to this order.",
        "parameters":{"type":"object","properties":{"id":{"type":"string"}},"required":["id"],"additionalProperties":false}}},
      {"type":"function","function":{"name":"read_dependency_result","description":"Read a SHA-verified UTF-8 page of an original dependency or delegated child result in this private workflow. Only the current node's original dependencies and children are accessible. Follow next_offset to read the complete result.",
        "parameters":{"type":"object","properties":{"node_id":{"type":"string"},"offset":{"type":"integer","minimum":0}},"required":["node_id","offset"],"additionalProperties":false}}},
      {"type":"function","function":{"name":"list_files","description":"List a selected folder. Use a granted folder_id and a relative directory path, or '.' for its root.",
        "parameters":{"type":"object","properties":{"folder_id":{"type":"string"},"path":{"type":"string"}},"required":["folder_id","path"],"additionalProperties":false}}},
      {"type":"function","function":{"name":"read_text_file","description":"Read a UTF-8 file in a selected folder and obtain its SHA-256 for a later edit. Maximum 1 MB.",
        "parameters":{"type":"object","properties":{"folder_id":{"type":"string"},"path":{"type":"string"}},"required":["folder_id","path"],"additionalProperties":false}}},
      {"type":"function","function":{"name":"stat_file","description":"Inspect a file or directory and obtain its current SHA-256 for rename/removal. Directory hashes cover the complete retained tree; no link traversal. File limit 64 MiB, tree limit 512 MiB and 10000 entries.",
        "parameters":{"type":"object","properties":{"folder_id":{"type":"string"},"path":{"type":"string"}},"required":["folder_id","path"],"additionalProperties":false}}},
      {"type":"function","function":{"name":"create_directory","description":"Create one new directory in a granted folder. The parent must exist. An existing destination is never replaced.",
        "parameters":{"type":"object","properties":{"folder_id":{"type":"string"},"path":{"type":"string"}},"required":["folder_id","path"],"additionalProperties":false}}},
      {"type":"function","function":{"name":"rename_file","description":"Move or rename a file or directory inside one granted folder. Use its SHA-256 from stat_file. The destination must not exist; existing files are never overwritten. The original contents are retained.",
        "parameters":{"type":"object","properties":{"folder_id":{"type":"string"},"path":{"type":"string"},"destination":{"type":"string"},"expected_sha256":{"type":"string"}},"required":["folder_id","path","destination","expected_sha256"],"additionalProperties":false}}},
      {"type":"function","function":{"name":"remove_file","description":"Remove a file or directory tree from the visible folder. Its contents are retained privately for recovery. Use its exact SHA-256 from stat_file; changed contents are rejected.",
        "parameters":{"type":"object","properties":{"folder_id":{"type":"string"},"path":{"type":"string"},"expected_sha256":{"type":"string"}},"required":["folder_id","path","expected_sha256"],"additionalProperties":false}}},
      {"type":"function","function":{"name":"restore_file","description":"Restore retained file content or a directory tree from an immutable receipt in this order into an absent path in the same granted folder. No provider is needed for native user restorations. Existing destinations are never overwritten; contents and provenance are verified.",
        "parameters":{"type":"object","properties":{"folder_id":{"type":"string"},"path":{"type":"string"},"source":{"type":"object","properties":{"run_id":{"type":"string"},"tool_call_id":{"type":"string"},"version":{"type":"string","enum":["text_before","text_after","operation_before","operation_after"]}},"required":["run_id","tool_call_id","version"],"additionalProperties":false}},"required":["folder_id","path","source"],"additionalProperties":false}}},
      {"type":"function","function":{"name":"write_text_file","description":"Create or replace one UTF-8 file in a writable selected folder. For replacement use the SHA-256 returned by read_text_file; null permits creation only. Existing parent directories must exist. Changes require the configured approval.",
        "parameters":{"type":"object","properties":{"folder_id":{"type":"string"},"path":{"type":"string"},"content":{"type":"string"},"expected_sha256":{"type":["string","null"]}},"required":["folder_id","path","content","expected_sha256"],"additionalProperties":false}}},
      {"type":"function","function":{"name":"execute_program","description":"Run a registered program in the explicitly selected qualified environment and this order's managed workspace. Arguments are literal; host paths, shell strings, environment variables and credentials cannot be selected. Mutating execution uses the configured exact approval. Unknown outcomes are never automatically retried.",
        "parameters":{"type":"object","properties":{"program":{"type":"string"},"arguments":{"type":"array","items":{"type":"string"}},"timeout_seconds":{"type":"integer","minimum":1,"maximum":86400}},"required":["program","arguments","timeout_seconds"],"additionalProperties":false}}},
      {"type":"function","function":{"name":"browser","description":"Use the selected browser session shared with the app UI. engine chrome or firefox and mode managed or extension explicitly create a new session; extension requires connection_id from the user. Omit session_id to use the user-selected session, or a legacy private Chromium session when none is selected. Manual takeover blocks AI input until the user resumes AI. Use control with a JSON BrowserCommand in text for tab_id/document_id and pointer, key, select, scroll, back, forward, reload or tab operations. Each concrete action requires exact approval. Never retry an uncertain effect.","parameters":{"type":"object","properties":{"engine":{"type":"string","enum":["chrome","firefox"]},"mode":{"type":"string","enum":["managed","extension"]},"connection_id":{"type":"string"},"session_id":{"type":"string"},"operation":{"type":"string","enum":["navigate","dom","screenshot","click","fill","fetch_text","search","annotate","annotations","clear_annotations","console","network","network_details","control","tabs","back","forward","reload"]},"url":{"type":"string"},"selector":{"type":"string"},"text":{"type":"string"}},"required":["operation"],"additionalProperties":false}}},
      {"type":"function","function":{"name":"office","description":"Request an exact user-approved native Office/PDF action. Input/output paths are relative to the order workspace. Native tools have server owner OS rights.","parameters":{"type":"object","properties":{"operation":{"type":"string"},"input":{"type":"string"},"output":{"type":"string"},"text":{"type":"string"},"title":{"type":"string"}},"required":["operation"],"additionalProperties":false}}},
      {"type":"function","function":{"name":"github","description":"Request an exact user-approved GitHub adapter action using the server's configured authority.","parameters":{"type":"object","properties":{"arguments":{"type":"array","items":{"type":"string"}}},"required":["arguments"],"additionalProperties":false}}},
      {"type":"function","function":{"name":"request_input","description":"Ask the user for information needed to continue.",
        "parameters":{"type":"object","properties":{"question":{"type":"string"}},"required":["question"],"additionalProperties":false}}}
    ]);
    let mut entries = catalog.as_array().expect("catalog").clone();
    // Appended after the original entries, so filtered catalogs of stored runs stay byte-identical.
    entries.extend(document_tool_catalog());
    let mut tools: Vec<Value> = entries
        .iter()
        .filter(|t| {
            t["function"]["name"]
                .as_str()
                .is_some_and(|n| spec.allowed_tools.iter().any(|a| a == n))
        })
        .cloned()
        .collect();
    if spec.executor == "android_private_server_linux" {
        for tool in &mut tools {
            if tool["function"]["name"] == "github" {
                tool["function"] = json!({"name":"github","description":"Use the exact user-approved operation with this actor's selected repository binding in an isolated network-none guest. open starts credential-free repository metadata; clone imports a selected repository. Retain session_id for subsequent operations. Mutating commit/push/PR actions require explicit original HEAD, tree and remote expectations. Credentials stay in the daemon's exact GitHub-origin broker. Unknown operations are never resent; files publish only after original removal and unchanged workspace baseline.","parameters":{"type":"object","properties":{"operation":{"type":"string","enum":["open","clone","fetch","pull","checkout","status","commit","push","close","pr_list","pr_view","pr_create","pr_merge","pr_close","issue_list","issue_view","issue_create","issue_comment","issue_close"]},"session_id":{"type":"string"},"directory":{"type":"string"},"branch":{"type":"string"},"base":{"type":"string"},"create_branch":{"type":"boolean"},"expected_head":{"type":"string"},"expected_remote":{"type":"string"},"expected_tree_sha256":{"type":"string"},"message":{"type":"string"},"number":{"type":"integer","minimum":1},"title":{"type":"string"},"body":{"type":"string"},"draft":{"type":"boolean"},"merge_method":{"type":"string","enum":["merge","squash","rebase"]}},"required":["operation"],"additionalProperties":false}});
            }
            if tool["function"]["name"] == "browser" {
                tool["function"] = json!({"name":"browser","description":"Use an exact user-approved browser action in this actor-private isolated run. Omit session_id for a new navigate, fetch_text or search session. The same live Chromium context persists until close or run end. Every action must explicitly list allowed HTTP(S) origins and allowed methods; redirects and subresources outside these origins are denied. Search uses the HTML DuckDuckGo URL and text query. Credentials belong only to this session. Browser files are promoted after confirmed guest removal and an unchanged workspace baseline; close before editing workspace files through another tool. Unknown actions are never replayed.","parameters":{"type":"object","properties":{"session_id":{"type":"string"},"operation":{"type":"string","enum":["navigate","fetch_text","search","dom","screenshot","click","fill","close"]},"url":{"type":"string"},"selector":{"type":"string"},"text":{"type":"string"},"allowed_origins":{"type":"array","minItems":1,"maxItems":16,"items":{"type":"string"}},"allowed_methods":{"type":"array","minItems":1,"maxItems":7,"items":{"type":"string","enum":["GET","HEAD","POST","PUT","PATCH","DELETE","OPTIONS"]}}},"required":["operation","allowed_origins","allowed_methods"],"additionalProperties":false}});
            }
            if tool["function"]["name"] == "office" {
                tool["function"]["description"] = json!(
                    "Request an exact user-approved Office/PDF action in the isolated private run workspace. Input and output are relative paths in that workspace. Supported operations: read_text, read_docx, read_xlsx, read_pdf, read_pptx, write_text, create_docx, create_xlsx, create_pptx, create_pdf, convert. The selected private image supplies libraries and LibreOffice. File changes and original results are retained in this run."
                );
            }
        }
    }
    tools.extend(spec.mcp_tools.iter().filter(|b| spec.allowed_tools.contains(&b.alias))
        .map(|binding| json!({"type":"function","function":{
            "name":binding.alias,
            "description":binding.definition.get("description").and_then(Value::as_str).unwrap_or("Selected external MCP tool"),
            "parameters":binding.definition["inputSchema"]
        }})));
    Value::Array(tools)
}

fn document_tool_catalog() -> Vec<Value> {
    vec![
        json!({"type":"function","function":{"name":"document_read","description":"Read a DOCX, XLSX, PPTX, PDF, text/TeX file or image in a granted folder. text: paginated text (follow next_offset). inspect: numbered structure plus source_sha256 for document_write edit. metadata: format, pages, size. preview: render pages/slides/images so you can check the layout. ocr: recognize scanned PDF/image pages with the optional local OCR runtime; returns word boxes, page/raster/source hashes and raw scores (not probabilities). OCR offset/limit count words; follow next_offset and next_page. languages deu/eng, dpi 100-400, clockwise rotation 0/90/180/270. help: the complete spec reference for document_write and image_edit; read the matching topic before your first create or edit.",
        "parameters":{"type":"object","properties":{"operation":{"type":"string","enum":["text","inspect","metadata","preview","ocr","help"]},"folder_id":{"type":"string"},"path":{"type":"string"},"offset":{"type":"integer","minimum":0},"limit":{"type":"integer","minimum":1,"maximum":100},"sheet":{"type":"string"},"pages":{"type":"array","items":{"type":"integer","minimum":1},"maxItems":16},"expected_sha256":{"type":"string","pattern":"^[0-9a-f]{64}$"},"languages":{"type":"array","items":{"type":"string","enum":["deu","eng"]},"minItems":1,"maxItems":2,"uniqueItems":true},"dpi":{"type":"integer","minimum":100,"maximum":400},"rotation":{"type":"integer","enum":[0,90,180,270]},"topic":{"type":"string","enum":["overview","docx","xlsx","pptx","pdf","latex","image"]}},"required":["operation"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"document_write","description":"Create or change Word, Excel, PowerPoint and PDF files. Every result is a new file: output.path must not exist yet and nothing is overwritten (write e.g. report-v2.docx). Omit output.folder_id to use the working folder. Operations: create (spec.format docx|xlsx|pptx with content), edit (inputs[0] with expected_sha256 from document_read inspect, spec.patches), pdf (spec.action merge|split|extract_pages|rotate|reorder|delete_pages|watermark|fill_form|set_metadata), compile_latex (inputs[0] is a .tex file written with write_text_file, further inputs are its images or .bib files; errors come back as file:line messages to fix), create_pdf (spec.markdown or spec.blocks with a built-in layout; LaTeX when available), convert (needs LibreOffice). Use document_read help for the exact spec. Set preview true to see the rendered result.",
        "parameters":{"type":"object","properties":{"operation":{"type":"string","enum":["create","edit","pdf","compile_latex","create_pdf","convert"]},"inputs":{"type":"array","maxItems":16,"items":{"type":"object","properties":{"folder_id":{"type":"string"},"path":{"type":"string"},"expected_sha256":{"type":"string"}},"required":["folder_id","path"],"additionalProperties":false}},"output":{"type":"object","properties":{"folder_id":{"type":"string"},"path":{"type":"string"}},"required":["path"],"additionalProperties":false},"spec":{"type":"object"},"preview":{"type":"boolean"}},"required":["operation","output"],"additionalProperties":false}}}),
        json!({"type":"function","function":{"name":"image_edit","description":"Edit an image into a new file; the original is never changed. steps run in order, each {\"op\":...}: crop{box:[left,top,right,bottom]}, crop_relative{box 0-1}, resize{width,height,fit:contain|cover|stretch}, thumbnail{max_edge}, rotate{degrees}, flip{direction:horizontal|vertical}, auto_orient, adjust{brightness,contrast,saturation,sharpness; 1.0 = unchanged}, grayscale, blur{radius}, sharpen{amount}, text{text,x,y,size,color}, arrow{from:[x,y],to:[x,y],color,width}, rectangle{box,color,width,fill}, ellipse{box,color,width}, pad{all,color}, border{width,color}, overlay{input:1,x,y,opacity,scale}, convert{mode}. Coordinates are pixels from the top-left; get the size with document_read metadata first. The output extension sets the format (png, jpg, webp). EXIF data is removed unless keep_exif is true. Set preview true to see the result.",
        "parameters":{"type":"object","properties":{"input":{"type":"object","properties":{"folder_id":{"type":"string"},"path":{"type":"string"},"expected_sha256":{"type":"string"}},"required":["folder_id","path"],"additionalProperties":false},"output":{"type":"object","properties":{"folder_id":{"type":"string"},"path":{"type":"string"}},"required":["path"],"additionalProperties":false},"steps":{"type":"array","minItems":1,"maxItems":50,"items":{"type":"object"}},"overlays":{"type":"array","maxItems":8,"items":{"type":"object","properties":{"folder_id":{"type":"string"},"path":{"type":"string"}},"required":["folder_id","path"],"additionalProperties":false}},"quality":{"type":"integer","minimum":1,"maximum":100},"keep_exif":{"type":"boolean"},"preview":{"type":"boolean"}},"required":["input","output","steps"],"additionalProperties":false}}}),
    ]
}
